files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --secondary: #0f3460;
  --secondary-hover: #1a4a7a;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --border: #2a2a4a;
  --success: #4ecca3;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: 
    linear-gradient(45deg, var(--border) 25%, transparent 25%),
    linear-gradient(-45deg, var(--border) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--border) 75%),
    linear-gradient(-45deg, transparent 75%, var(--border) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 480px;
}

.game-card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 32px 24px;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #000;
}

.subtitle {
  color: var(--text-muted);
  margin-bottom: 24px;
  font-size: 1rem;
}

.game-area {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

label {
  font-weight: 600;
  text-align: left;
  display: block;
  margin-bottom: 4px;
}

.input-group {
  display: flex;
  gap: 8px;
}

input[type="number"] {
  flex: 1;
  padding: 12px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  border-radius: 0;
  outline: none;
  min-width: 0;
}

input[type="number"]:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

input[type="number"]::placeholder {
  color: var(--text-muted);
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 20px;
  border: 3px solid transparent;
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.btn.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.btn.primary:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.btn.secondary {
  background: var(--secondary);
  color: var(--text);
  border-color: var(--border);
}

.btn.secondary:hover {
  background: var(--secondary-hover);
}

.btn.secondary:active {
  transform: translate(2px, 2px);
}

.btn:focus-visible {
  outline: 3px solid var(--success);
  outline-offset: 2px;
}

.feedback {
  min-height: 1.5em;
  font-size: 1.125rem;
  font-weight: 600;
  padding: 8px;
  border: 3px dashed var(--border);
  background: var(--bg);
}

.feedback.too-high {
  color: var(--primary);
  border-color: var(--primary);
}

.feedback.too-low {
  color: #f0c040;
  border-color: #f0c040;
}

.feedback.correct {
  color: var(--success);
  border-color: var(--success);
}

.guess-count {
  font-size: 1rem;
  color: var(--text-muted);
  font-weight: 600;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .input-group {
    flex-direction: column;
  }
  .btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  const guessInput = document.getElementById('guessInput');
  const guessBtn = document.getElementById('guessBtn');
  const newGameBtn = document.getElementById('newGameBtn');
  const feedback = document.getElementById('feedback');
  const guessCountEl = document.getElementById('guessCount');

  let secretNumber = 0;
  let guessCount = 0;
  let gameOver = false;

  function startGame() {
    secretNumber = Math.floor(Math.random() * 100) + 1;
    guessCount = 0;
    gameOver = false;
    feedback.textContent = 'Enter a number and press Guess.';
    feedback.className = 'feedback';
    guessCountEl.textContent = 'Guesses: 0';
    guessInput.value = '';
    guessInput.disabled = false;
    guessBtn.disabled = false;
    guessInput.focus();
  }

  function handleGuess() {
    if (gameOver) return;

    const value = parseInt(guessInput.value, 10);
    if (isNaN(value) || value < 1 || value > 100) {
      feedback.textContent = 'Please enter a number between 1 and 100.';
      feedback.className = 'feedback';
      guessInput.focus();
      return;
    }

    guessCount++;
    guessCountEl.textContent = 'Guesses: ' + guessCount;

    if (value === secretNumber) {
      feedback.textContent = 'Correct! You guessed it in ' + guessCount + ' guess' + (guessCount === 1 ? '' : 'es') + '!';
      feedback.className = 'feedback correct';
      gameOver = true;
      guessInput.disabled = true;
      guessBtn.disabled = true;
    } else if (value > secretNumber) {
      feedback.textContent = 'Too high! Try a lower number.';
      feedback.className = 'feedback too-high';
      guessInput.value = '';
      guessInput.focus();
    } else {
      feedback.textContent = 'Too low! Try a higher number.';
      feedback.className = 'feedback too-low';
      guessInput.value = '';
      guessInput.focus();
    }
  }

  guessBtn.addEventListener('click', handleGuess);

  guessInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleGuess();
    }
  });

  newGameBtn.addEventListener('click', startGame);

  startGame();
})();
